import '@servicenow/sdk/global'
import { StringColumn } from '@servicenow/sdk/core'
import { Flow, wfa, action } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['flow_label_cache_dedup'],
        name: 'Flow Label Cache - Deduplication',
        description: 'Tests label cache deduplication across multiple instances',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
        flowVariables: {
            userId: StringColumn({
                mandatory: true,
                label: 'User Identifier',
                max_length: 32,
            }),
            actionType: StringColumn({
                mandatory: true,
                label: 'Action Type',
                max_length: 50,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['label_cache_dedup_trigger'] },
        {
            table: 'sys_user',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_setting: 'both',
            run_when_user_list: [],
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['dedup_step1'] },
            {
                log_message: `Validating user: ${wfa.dataPill(params.flowVariables.userId, 'string')}`,
                log_level: 'info',
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['dedup_step2'] },
            {
                log_message: `User: ${wfa.dataPill(params.flowVariables.userId, 'string')}, Action: ${wfa.dataPill(params.flowVariables.actionType, 'string')}`,
                log_level: 'info',
            }
        )

        wfa.flowLogic.if(
            {
                $id: Now.ID['dedup_step3'],
                condition: `${wfa.dataPill(params.flowVariables.userId, 'string')}!=null`,
                annotation: 'Check if user ID exists',
            },
            () => {
                wfa.action(
                    action.core.log,
                    { $id: Now.ID['dedup_step4'] },
                    {
                        log_message: `Processing user: ${wfa.dataPill(params.flowVariables.userId, 'string')}`,
                        log_level: 'info',
                    }
                )
            }
        )
    }
)
